Analisando o problema: precisamos da maior sequência de visitas a tendas começando no palácio (0,0), onde as distâncias percorridas consecutivamente são estritamente decrescentes e a mesma tenda não pode ser visitada em movimentos consecutivos (revisitas não consecutivas são permitidas — o Exemplo 1 exige isso, e o Exemplo 3 mostra que não é permitido parar no palácio no meio do caminho).

**Abordagem:** DP sobre arestas dirigidas. Estado f(u→v) = máximo de visitas terminando com o movimento u→v. Recorrência: f(u→v) = 1 + max{f(x→u) : w(x,u) > w(u,v)} com caso base f(palácio→v) = 1. Ordenamos todos os pares por distância (decrescente), processamos em grupos de pesos iguais (atualizações do grupo são adiadas para impor a desigualdade estrita), mantendo `best[v]` = melhor valor de f chegando em v. Usamos distâncias ao quadrado (inteiros exatos) e chaves empacotadas em doubles (peso×2²² + payload, exato < 2⁵³) para uma ordenação nativa rápida. Complexidade O(N² log N), memória ~40MB, rápido para N=2000.

```javascript
const fs = require('fs');

function main() {
  const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
  const N = tokens[0];
  if (!(N >= 1)) {
    console.log(0);
    return;
  }

  const xs = new Float64Array(N);
  const ys = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    xs[i] = tokens[1 + 2 * i];
    ys[i] = tokens[2 + 2 * i];
  }

  const BASE = 4194304; // 2^22
  const INV = 1 / BASE; // exato (2^-22)
  const ORI = 4192256;  // 2047*2048, marca de aresta saindo do palácio

  const E = (N * (N - 1)) / 2 + N;
  const keys = new Float64Array(E);

  let idx = 0;
  for (let i = 0; i < N; i++) {
    const xi = xs[i], yi = ys[i], bi = i * 2048;
    for (let j = i + 1; j < N; j++) {
      const dx = xi - xs[j], dy = yi - ys[j];
      keys[idx++] = (dx * dx + dy * dy) * BASE + (bi + j);
    }
  }
  for (let i = 0; i < N; i++) {
    keys[idx++] = (xs[i] * xs[i] + ys[i] * ys[i]) * BASE + (ORI + i);
  }

  keys.sort(); // ordenação numérica ascendente (padrão de TypedArray)

  // best[v] = melhor f entre arestas dirigidas que chegam em v já processadas
  // (todas com peso estritamente maior que o grupo atual); 0 = nenhuma ainda
  const best = new Int32Array(N);
  const TCAP = N * (N - 1) + N + 2;
  const tmpV = new Uint16Array(TCAP);
  const tmpF = new Int32Array(TCAP);

  let ans = 1; // sempre é possível visitar 1 tenda
  let cnt = 0;
  let prevW = -1;

  for (let k = E - 1; k >= 0; k--) {
    const key = keys[k];
    const w = (key * INV) | 0;
    if (w !== prevW) {
      // aplica atualizações do grupo anterior (peso estritamente maior)
      for (let t = 0; t < cnt; t++) {
        const f = tmpF[t], v = tmpV[t];
        if (f > best[v]) best[v] = f;
      }
      cnt = 0;
      prevW = w;
    }
    const payload = key - w * BASE;
    if (payload >= ORI) {
      // palácio -> tenda v: primeira visita, f = 1
      tmpV[cnt] = payload - ORI;
      tmpF[cnt] = 1;
      cnt++;
    } else {
      const u = (payload / 2048) | 0;
      const v = payload - u * 2048;
      const bu = best[u];
      if (bu > 0) {
        const f = bu + 1; // ... -> u -> v
        tmpV[cnt] = v; tmpF[cnt] = f; cnt++;
        if (f > ans) ans = f;
      }
      const bv = best[v];
      if (bv > 0) {
        const f = bv + 1; // ... -> v -> u
        tmpV[cnt] = u; tmpF[cnt] = f; cnt++;
        if (f > ans) ans = f;
      }
    }
  }
  for (let t = 0; t < cnt; t++) {
    const f = tmpF[t], v = tmpV[t];
    if (f > best[v]) best[v] = f;
  }

  console.log(ans);
}

main();
```

